def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p):return os.path.relpath(p,O)
def ref(p):
    assert p.is_file() and p.stat().st_size<100_000_000,p
    return {'path':rel(p),'sha256':sha(p),'bytes':p.stat().st_size}
def write(p,v):
    assert not p.exists(),p
    p.write_text(json.dumps(v,indent=2,sort_keys=True)+'\n')
